+import { shuffle } from "./shuffle";
+import { constant } from "./constant";
+
+const SYMBOLS = times(100, (i) => Symbol(`sym${i.toString()}`));
+const CHARACTERS = [
+  // eslint-disable-next-line @typescript-eslint/no-misused-spread
