+  // Only convert to object at the end
+  return Object.fromEntries(output.entries()) as ExactRecord<
+    Key,
+    NonEmptyArray<T>
+  >;
+};
+
+const groupByImplementationAlt = <T, Key extends PropertyKey = PropertyKey>(
+  data: ReadonlyArray<T>,
+  callbackfn: (
+    value: T,
+    index: number,
+    data: ReadonlyArray<T>,
+  ) => Key | undefined,
