+      } else {
+        // @ts-expect-error -- See full impl...
+        items.push(item);
+      }
+    }
+  }
+
+  Object.setPrototypeOf(output, Object.prototype);
+
+  return output;
+};
+
+function generateRandomIntegers(size: number) {
