+    times(keyLength, () => sample(CHARACTERS, 1)).join(""),
+  );
+}
+
+function generateRandomUsers(size: number) {
+  return times(size, () => ({
+    id: randomInteger(1, 1_000_000),
+    age: randomInteger(18, 80),
+    region: sample(REGIONS, 1)[0],
+  }));
+}

