+    expect(mockFn).toHaveBeenCalledTimes(1);
+    expect(mockFn).toHaveBeenLastCalledWith(undefined, "a");
+
+    foo.call("b");
+    foo.call("c");
+
+    expect(mockFn).toHaveBeenCalledTimes(1);
