+  });
+});
+
+it("makes the result mutable", () => {
+  const data = [] as ReadonlyArray<number>;
+
+  pipe(data, forEach(doNothing()), (x) => {
+    expectTypeOf(x).toEqualTypeOf<Array<number>>();
+  });
+});

