+ * @example
+ *    R.isBigInt(1n); // => true
+ *    R.isBigInt(1); // => false
+ *    R.isBigInt('notANumber'); // => false
+ * @category Guard
+ */
+export function isBigInt<T>(data: T | bigint): data is NarrowedTo<T, bigint> {
+  return typeof data === "bigint";
+}

