@@ -0,0 +1,23 @@
+import type FUNCTIONS from "@/data/functions.json";
+
+export function getTags({
+  methods: [method],
+}: (typeof FUNCTIONS)[number]): ReadonlyArray<string> {
+  const { pipeable = false, indexed = false, strict = false } = method ?? {};
+
+  const out = [];
+
+  if (pipeable) {
+    out.push("pipeable");
+  }
+
+  if (indexed) {
+    out.push("indexed");
+  }
+
+  if (strict) {
+    out.push("strict");
+  }
+
+  return out;
+}

