+    expect(sliceString(-10)(ALPHABET)).toEqual('qrstuvwxyz');
+  });
+
+  test('alphabet, >0 indexStart, >len', () => {
+    expect(sliceString(100)(ALPHABET)).toEqual('');
+  });
